#!/usr/bin/env node
/**
 * cadre/copy-template.js, the first email for leads found by title and size rather than by a
 * job posting (source 'prospeo', personalization_basis 'industry-template').
 *
 * There is no sentence of theirs to quote, so the email states only what is on the row: the
 * person's title, the company, its headcount, and the credentials that sector actually has to
 * keep current. Nothing is generated by a model, nothing is inferred about how they do it today,
 * and the close is the campaign's standard {{ASK}}. Under 90 words like every other first touch.
 *
 * The credential list per sector is the one thing a reader could dispute, so it names only
 * requirements that are near universal in that sector in Canada and the US (fall protection and
 * first aid on construction sites, driver qualification files under FMCSA, and so on).
 *
 *   node cadre/copy-template.js --dry --limit 5
 *   node cadre/copy-template.js
 */
const path = require('path');
require('dotenv').config({ path: path.join(__dirname, '..', '.env'), quiet: true });
const supabase = require('../lib/supabase');

const DRY = process.argv.includes('--dry');
const arg = (name, dflt) => { const i = process.argv.indexOf(`--${name}`); return i > -1 ? process.argv[i + 1] : dflt; };
const LIMIT = parseInt(arg('limit', '500'), 10);
// --rewrite: replace earlier template copy (never hand-written, locked copy) after the wording changes.
const REWRITE = process.argv.includes('--rewrite');

/** Sector wording, keyed by a regex over the Prospeo industry string kept in notes, then ours. */
const SECTORS = [
  [/construction|contractor|utility system/i, 'construction', 'fall protection, first aid and equipment tickets', 'training records'],
  [/truck|freight|transportation|logistics|warehous|supply chain/i, 'transport', 'driver qualification files, medical cards and licences', 'driver qualification files'],
  [/manufactur|machinery|fabricat|plastics|metal|food and beverage/i, 'manufacturing', 'forklift tickets, WHMIS, lockout and first aid renewals', 'training records'],
  [/hospital|health care|home health|mental health|clinic|care/i, 'health care', 'licences, CPR and mandatory training', 'certification records'],
  [/oil|gas|mining|energy/i, 'oil and gas', 'H2S, first aid, confined space and site orientations', 'safety tickets'],
  [/utilit|electric|environmental/i, 'utilities', 'safety tickets and technical certifications', 'certification records'],
  [/security|facilities/i, 'facilities and security', 'security licences, first aid and site training', 'certification records'],
  [/non-?profit|family|community|child|day care|social/i, 'community services', 'record checks, first aid and mandatory training', 'training records'],
];
const DEFAULT = ['your sector', 'the certifications and mandatory training your people hold', 'certification records'];

function sector(lead) {
  const hint = `${((lead.notes || '').match(/industry ([^,\n]+)/) || [])[1] || ''} ${lead.industry || ''} ${lead.business_name || ''}`;
  for (const [re, noun, creds, subject] of SECTORS) if (re.test(hint)) return { noun, creds, subject };
  return { noun: DEFAULT[0], creds: DEFAULT[1], subject: DEFAULT[2] };
}

function firstName(full) { return String(full || '').trim().split(/\s+/)[0] || 'there'; }

/** "Human Resources Manager" -> "run HR"; "Director of Human Resources" -> "run HR"; safety -> "run safety". */
function roleVerb(title) {
  const t = String(title || '').toLowerCase();
  if (/safety|hse|ehs/.test(t)) return 'run safety';
  if (/training|learning/.test(t)) return 'run training';
  if (/operation|coo/.test(t)) return 'run operations';
  return 'run HR';
}

function body(lead) {
  const s = sector(lead);
  const n = lead.staff_estimate;
  // Written from the reader's side (Aidan, 2026-09-16: "make everything about the other person").
  // Paragraph one is their Tuesday. Paragraph two is the outcome, not the product; the product is
  // named in one clause because the signature and the ask assume it exists.
  return `Hi ${firstName(lead.contact_name)},

At ${n} people, someone at ${lead.business_name} keeps ${s.creds} current for all of them, and hears about the expired one on the morning it matters.

There is a version of that where completing the course updates the record itself and the renewal is already on the calendar, next to onboarding, signed policies and reviews. That is what I build for companies your size.

{{ASK}}`;
}

(async () => {
  const { data, error } = await supabase.from('cadre_leads')
    .select('id, business_name, contact_name, contact_role, staff_estimate, industry, notes, email_body, copy_locked')
    .eq('status', 'queued').eq('personalization_basis', 'industry-template')
    .not('contact_name', 'is', null).not('staff_estimate', 'is', null)
    .order('qualification_score', { ascending: false, nullsFirst: false }).limit(LIMIT);
  if (error) throw new Error(error.message);
  let wrote = 0, skipped = 0;
  for (const lead of data) {
    if (lead.copy_locked) { skipped++; continue; }
    if (lead.email_body && !REWRITE) { skipped++; continue; }
    const text = body(lead);
    const words = text.replace(/\{\{ASK\}\}/, '').trim().split(/\s+/).length;
    if (words > 90) { console.log(`  --   ${lead.business_name}  ${words} words, over the limit`); skipped++; continue; }
    const subj = sector(lead).subject;
    console.log(`  ok   ${String(lead.business_name).slice(0, 32).padEnd(34)}${subj.padEnd(28)}${words}w  ${firstName(lead.contact_name)}, ${lead.contact_role || ''}`);
    if (DRY && wrote < 3) console.log('\n' + text.split('\n').map((l) => '       ' + l).join('\n') + '\n');
    if (!DRY) {
      const { error: e } = await supabase.from('cadre_leads').update({ email_subject: subj, email_body: text }).eq('id', lead.id);
      if (e) { console.log(`       write failed: ${e.message}`); skipped++; continue; }
    }
    wrote++;
  }
  console.log(`\n${DRY ? 'Would write' : 'Wrote'} ${wrote} | skipped ${skipped}`);
})().catch((e) => { console.error(e.message); process.exit(1); });
